1	// How a scenario unfolds. This module knows the order events happen in and
2	// what each step leaves behind for the next one; it delegates what a policy
3	// costs to pricing.ts and what it pays out to coverage.ts.
4	
5	import { premiumFor, type Customer, type Item } from "./pricing.js";
6	import {
7	  capFor,
8	  payoutForDamages,
9	  settleClaim,
10	  type Damage,
11	} from "./coverage.js";
12	
13	export type { Customer, KnownItemType } from "./pricing.js";
14	export type { Damage } from "./coverage.js";
15	
16	export interface Scenario {
17	  customer: Customer;
18	  steps: Step[];
19	}
20	
21	export interface QuoteStep {
22	  op: "quote";
23	  items: Item[];
24	}
25	
26	export interface ClaimStep {
27	  op: "claim";
28	  policy: number;
29	  incident: { cause: string; damages: Damage[] };
30	}
31	
32	export type Step = QuoteStep | ClaimStep;
33	
34	export interface ScenarioResults {
35	  results: ({ premium: number } | { payout: number; remainingCap: number })[];
36	}
37	
38	// What earlier steps have established by the time a later step is priced.
39	// Steps are not independent: a quote is a follow-up contract when the customer
40	// already took a quote earlier in the same scenario. Folding this forward —
41	// rather than re-deriving it from the step prefix — is what lets a step read
42	// the state its predecessors left behind.
43	interface Policy {
44	  // The insured items, kept because a claim is settled against them: what a
45	  // damage reimburses depends on the item's own material and enchantment, not
46	  // on the damage entry alone.
47	  items: Item[];
48	  remainingCap: number;
49	}
50	
51	interface ScenarioState {
52	  hasQuoted: boolean;
53	  // Keyed by the step index of the quote that created the policy, which is
54	  // how a later claim step refers to it.
55	  policies: Map<number, Policy>;
56	}
57	
58	const INITIAL_STATE: ScenarioState = { hasQuoted: false, policies: new Map() };
59	
60	type StepOutcome = ScenarioResults["results"][number];
61	
62	interface StepRun {
63	  outcome: StepOutcome;
64	  state: ScenarioState;
65	}
66	
67	// Every policy a step establishes is recorded the same way, so both handlers
68	// go through here rather than each rebuilding the map.
69	const withPolicy = (
70	  state: ScenarioState,
71	  index: number,
72	  policy: Policy,
73	): ScenarioState => ({
74	  ...state,
75	  policies: new Map(state.policies).set(index, policy),
76	});
77	
78	const runQuote = (
79	  { items }: QuoteStep,
80	  customer: Customer,
81	  state: ScenarioState,
82	  index: number,
83	): StepRun => ({
84	  outcome: {
85	    premium: premiumFor(items, {
86	      customer,
87	      isFollowUpContract: state.hasQuoted,
88	    }),
89	  },
90	  state: withPolicy({ ...state, hasQuoted: true }, index, {
91	    items,
92	    remainingCap: capFor(items),
93	  }),
94	});
95	
96	const runClaim = (
97	  { policy: policyIndex, incident }: ClaimStep,
98	  state: ScenarioState,
99	): StepRun => {
100	  // A claim always names a policy an earlier quote step created. Nothing
101	  // validates that yet — the test rejecting unknown references will force the
102	  // question of what to do when it is absent.
103	  const policy = state.policies.get(policyIndex) ?? {
104	    items: [],
105	    remainingCap: 0,
106	  };
107	  const { payout, remainingCap } = settleClaim(
108	    payoutForDamages(policy.items, incident.damages),
109	    policy.remainingCap,
110	  );
111	
112	  return {
113	    outcome: { payout, remainingCap },
114	    state: withPolicy(state, policyIndex, { ...policy, remainingCap }),
115	  };
116	};
117	
118	// Dispatches a step to its handler. Written as an exhaustive switch on `op`
119	// so that adding a step kind to the Step union turns "I forgot to handle it"
120	// into a compile error rather than a wrong number.
121	const runStep = (
122	  step: Step,
123	  customer: Customer,
124	  state: ScenarioState,
125	  index: number,
126	): StepRun => {
127	  switch (step.op) {
128	    case "quote":
129	      return runQuote(step, customer, state, index);
130	    case "claim":
131	      return runClaim(step, state);
132	  }
133	};
134	
135	export const runScenario = ({ customer, steps }: Scenario): ScenarioResults => {
136	  const { results } = steps.reduce<{
137	    results: StepOutcome[];
138	    state: ScenarioState;
139	  }>(
140	    ({ results, state }, step, index) => {
141	      const stepRun = runStep(step, customer, state, index);
142	      return { results: [...results, stepRun.outcome], state: stepRun.state };
143	    },
144	    { results: [], state: INITIAL_STATE },
145	  );
146	
147	  return { results };
148	};
149

1	// What a policy costs. This module answers one question — given the items on
2	// a policy and the context the policy is written in, what premium does the
3	// customer pay? It knows nothing about scenarios, steps, or the order events
4	// happen in; see claim-office.ts for that. What a policy pays OUT is the
5	// mirror question, answered by coverage.ts.
6	
7	import { roundUpInFavourOfMHPCO } from "./rounding.js";
8	
9	export interface Customer {
10	  yearsWithMHPCO: number;
11	}
12	
13	const PROCESSING_FEE = 5;
14	const BASE_PREMIUM_BY_TYPE = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	} as const satisfies Record<string, number>;
22	
23	export type KnownItemType = keyof typeof BASE_PREMIUM_BY_TYPE;
24	
25	export interface Item {
26	  type: KnownItemType;
27	  material?: string;
28	  enchantment?: number;
29	  cursed?: boolean;
30	}
31	
32	const FIRST_INSURANCE_SURCHARGE = 0.1;
33	
34	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
35	
36	const BLOCK_SIZE = 3;
37	const BLOCK_BASE_PREMIUM = 60;
38	
39	const groupByType = (items: Item[]): Item[][] => [
40	  ...items
41	    .reduce(
42	      (groups, item) =>
43	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
44	      new Map<KnownItemType, Item[]>(),
45	    )
46	    .values(),
47	];
48	
49	const sumOfBasePremiums = (items: Item[]): number =>
50	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
51	
52	// Exactly three alike components form a block at a reduced premium; any
53	// other count is priced per item.
54	//
55	// Deliberate simplification: "component" is not yet enforced, so three alike
56	// swords would also get the block. No test covers it and the spec gives no
57	// example — revisit when one does.
58	const groupBasePremiumOf = (group: Item[]): number =>
59	  group.length === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : sumOfBasePremiums(group);
60	
61	const policyBasePremiumOf = (items: Item[]): number =>
62	  groupByType(items).reduce((sum, group) => sum + groupBasePremiumOf(group), 0);
63	
64	const CURSE_SURCHARGE = 0.5;
65	
66	// Item-specific modifiers are charged as a percentage of the affected item's
67	// OWN base premium. See withPolicyWideModifiers for the other scope.
68	const shareOfOwnBasePremium = (item: Item, rate: number): number =>
69	  basePremiumOf(item) * rate;
70	
71	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
72	const HIGH_ENCHANTMENT_THRESHOLD = 5;
73	
74	const isHighlyEnchanted = (item: Item): boolean =>
75	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
76	
77	const ITEM_SURCHARGES: { applies: (item: Item) => boolean; rate: number }[] = [
78	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
79	  { applies: isHighlyEnchanted, rate: HIGH_ENCHANTMENT_SURCHARGE },
80	];
81	
82	// Every modifier rate in this domain combines additively, whether item-scoped
83	// or policy-wide: two rates of +50 % and +30 % make +80 %, never +95 %.
84	const combinedRate = (rates: number[]): number =>
85	  rates.reduce((total, rate) => total + rate, 0);
86	
87	// Both item modifiers can apply at once, and they stack additively: a cursed
88	// item with enchantment 5 pays 50 % + 30 % of its base premium.
89	const surchargeRateOn = (item: Item): number =>
90	  combinedRate(
91	    ITEM_SURCHARGES.filter(({ applies }) => applies(item)).map(
92	      ({ rate }) => rate,
93	    ),
94	  );
95	
96	const surchargeOn = (item: Item): number =>
97	  shareOfOwnBasePremium(item, surchargeRateOn(item));
98	
99	const itemSurchargesOf = (items: Item[]): number =>
100	  items.reduce((sum, item) => sum + surchargeOn(item), 0);
101	
102	// Policy-wide modifiers scale the whole policy base premium, unlike item
103	// modifiers which are charged against the affected item's own base premium.
104	// They combine additively, so a policy carrying +10 % and -20 % pays 90 % of
105	// its base — not 110 % × 80 %.
106	const LOYALTY_DISCOUNT = -0.2;
107	const LOYALTY_THRESHOLD_YEARS = 2;
108	
109	const isLoyal = (customer: Customer): boolean =>
110	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
111	
112	const FOLLOW_UP_CONTRACT_DISCOUNT = -0.15;
113	
114	// Everything about the policy's context that shifts its rates, as opposed to
115	// the items being priced. Travels as one value because every policy-wide
116	// modifier reads from it.
117	export interface PolicyContext {
118	  customer: Customer;
119	  isFollowUpContract: boolean;
120	}
121	
122	const policyWideModifierRatesFor = ({
123	  customer,
124	  isFollowUpContract,
125	}: PolicyContext): number[] => [
126	  FIRST_INSURANCE_SURCHARGE,
127	  ...(isLoyal(customer) ? [LOYALTY_DISCOUNT] : []),
128	  ...(isFollowUpContract ? [FOLLOW_UP_CONTRACT_DISCOUNT] : []),
129	];
130	
131	const withPolicyWideModifiers = (
132	  policyBase: number,
133	  policy: PolicyContext,
134	): number =>
135	  policyBase * (1 + combinedRate(policyWideModifierRatesFor(policy)));
136	
137	export const premiumFor = (items: Item[], policy: PolicyContext): number =>
138	  roundUpInFavourOfMHPCO(
139	    withPolicyWideModifiers(policyBasePremiumOf(items), policy) +
140	      itemSurchargesOf(items) +
141	      PROCESSING_FEE,
142	  );
143

