// Which insured item a damage entry is about. A damage names its item by type,
// so the first item of that type answers it. That is exact while a policy
// holds at most one item per type; the test rejecting more damage entries of a
// type than the policy covers is what will force a real pairing.
const damagedItem = (items: Item[], damage: Damage): Item | undefined =>
  items.find((item) => item.type === damage.itemType);

export const payoutForDamages = (items: Item[], damages: Damage[]): number =>
  damages.reduce((total, damage) => {
    const item = damagedItem(items, damage);
    return total + (item === undefined ? 0 : netOfDeductible(item, damage));
  }, 0);

