// Which insured item a damage entry is paid against. A damage names its item
// by type only, so this answers with the first insured item of that type.
//
// Named for what it actually does rather than for the question it stands in
// for: it is NOT yet "the damaged item". Two damages of the same type both
// resolve to the same insured item, so a policy could pay twice for one sword.
// That is invisible while every example either holds one item per type or —
// as in the two-identical-swords case — pairs items that are indistinguishable
// anyway. The test rejecting more damage entries of a type than the policy
// covers is what forces real pairing, where each insured item is consumed at
// most once; at that point this becomes a fold over remaining items and earns
// the name `damagedItem`.
const firstItemOfDamagedType = (
  items: Item[],
  damage: Damage,
): Item | undefined => items.find((item) => item.type === damage.itemType);

export const payoutForDamages = (items: Item[], damages: Damage[]): number =>
  damages.reduce((total, damage) => {
    const item = firstItemOfDamagedType(items, damage);
    return total + (item === undefined ? 0 : netOfDeductible(item, damage));
  }, 0);
